#!/usr/bin/env python3
"""Generate the protocol reference and validate maintained local doc links."""

import argparse
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
OPERATIONS = ("hello", "auth", "list", "heads", "open", "read", "create", "append", "deposit",
              "put_manifest", "get_manifest", "blob_put", "blob_get")


def render(schema):
    lines = [
        "# FLINT-SYNC/1 reference", "",
        "<!-- Generated by python3 tools/docs.py; edit flint-sync.schema.json. -->", "",
        "Messages are newline-delimited JSON over TCP or stdio, not HTTP.",
        "The [JSON Schema](flint-sync.schema.json) describes wire objects.",
        "The [implementation spec](flint-server-spec.md) remains normative for",
        "canonical bytes, signatures, crash recovery, and authentication.", "",
        "## Requests", "",
        "`seq` is an unsigned 32-bit client correlator, echoed in replies.",
        "Omitting it currently defaults to zero; clients should always send it.", "",
        "| Operation | Required fields | Behavior |",
        "| --- | --- | --- |",
    ]
    for name in OPERATIONS:
        operation = schema["$defs"][name]
        fields = ", ".join(f"`{field}`" for field in operation["required"])
        lines.append(f"| `{name}` | {fields} | {operation['description']} |")
    lines += [
        "", "## Responses", "",
        "Every reply includes `seq` and `ok`. Refusals additionally include",
        "`refuse` and `detail`. Success payloads depend on the operation.", "",
        "Refusal vocabulary: " + ", ".join(
            f"`{code}`" for code in schema["$defs"]["response"]["properties"]["refuse"]["enum"]
        ) + ".", "",
        "One session has one request in flight. Lines are bounded to 4 MiB.",
        "There are at most 4096 changes per stream. `read` defaults to 256",
        "changes and caps a requested limit at 1024.", "",
        "## Authentication", "",
        "When configured, `hello` returns a random 16-byte nonce as lowercase hex.",
        '`auth` supplies the same nonce and HMAC-SHA256 over the bytes',
        '`"FLINT-SYNC-AUTH/1\\x00" || nonce`, using the external 32-byte key.',
        "Authentication failure closes the session. Use an encrypted tunnel",
        "for confidentiality; this protocol does not implement TLS.", "",
    ]
    return "\n".join(lines)


def broken_links(root):
    errors = []
    for name in ("README.md", "AGENTS.md", "CONTRIBUTING.md", "SECURITY.md",
                 "docs/protocol-reference.md", "docs/releases.md", "docs/runbooks/operations.md"):
        path = root / name
        if not path.exists():
            errors.append(f"{name}: missing maintained document")
            continue
        for target in re.findall(r"\[[^\]]*\]\(([^)\s]+)\)", path.read_text()):
            if ":" in target or target.startswith("#"):
                continue
            if not (path.parent / target.split("#", 1)[0]).exists():
                errors.append(f"{name}: broken link {target}")
    return errors


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    schema = json.loads((ROOT / "docs/flint-sync.schema.json").read_text())
    expected = render(schema)
    destination = ROOT / "docs/protocol-reference.md"
    if args.check:
        if not destination.exists() or destination.read_text() != expected:
            print("Protocol reference is stale; run python3 tools/docs.py")
            return 1
    else:
        destination.write_text(expected)
    errors = broken_links(ROOT)
    for error in errors:
        print(error)
    return int(bool(errors))


if __name__ == "__main__":
    raise SystemExit(main())
